selector_to_html = {"a[href=\"getting_started/install.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5b89\u88c5<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>FlagPrism \u901a\u8fc7 <code class=\"docutils literal notranslate\"><span class=\"pre\">third_party/FlagPrism</span></code> \u5b50\u6a21\u5757\u4f5c\u4e3a FlagTree wheel \u7684\u4e00\u90e8\u5206\u6784\u5efa\uff0c\u4e0d\u5355\u72ec\u53d1\u5e03\u4e3a\u72ec\u7acb\u5305\u3002</p>", "a[href=\"#flagprism\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagPrism<a class=\"headerlink\" href=\"#flagprism\" title=\"Link to this heading\">#</a></h1><p>FlagPrism \u662f\u9762\u5411 <a class=\"reference external\" href=\"https://github.com/triton-lang/triton\">Triton</a> \u7a0b\u5e8f\u7684\u591a\u540e\u7aef\u8c03\u8bd5\u4e0e\u6027\u80fd\u5206\u6790\u5de5\u5177\uff0c\u670d\u52a1\u4e8e <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree\">FlagTree</a> \u751f\u6001\u3002\u5b83\u96c6\u4e2d\u7ef4\u62a4 <code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree.debugger</span></code> \u4e0e <code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree.profiler</span></code> \u4e24\u4e2a\u7ec4\u4ef6\uff0c\u4e3a NVIDIA GPU \u53ca\u591a\u79cd AI \u52a0\u901f\u8bbe\u5907\u63d0\u4f9b\u4e00\u81f4\u7684\u89c2\u6d4b\u5de5\u4f5c\u6d41\u3002</p><p><a data-lightbox=\"image-set\" href=\"_images/flagprism-architecture.png\">\n<img alt=\"FlagPrism \u67b6\u6784\" src=\"_images/flagprism-architecture.png\"/></a>\n</p>", "a[href=\"user_guide/profiler.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Profiler<a class=\"headerlink\" href=\"#profiler\" title=\"Link to this heading\">#</a></h1><p>FlagTree Profiler \u662f\u9762\u5411 Triton \u7684\u8f7b\u91cf\u7ea7\u6027\u80fd\u5206\u6790\u5668\uff0c\u63d0\u4f9b\u4ece Python \u8c03\u7528\u7684 GPU kernel \u7684\u7a0b\u5e8f\u4e0a\u4e0b\u6587\u3001metadata \u548c\u786c\u4ef6\u6027\u80fd\u6307\u6807\uff0c\u5e76\u5c06\u8bb0\u5f55\u805a\u5408\u4e3a\u8c03\u7528\u6811\u3001\u65f6\u95f4\u7ebf\u3001Hatchet\u3001\u5143\u6570\u636e\u53ca\u5382\u5546\u76f8\u5173\u8f93\u51fa\u3002</p>", "a[href=\"overview/overview.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u6982\u89c8<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>FlagPrism \u662f\u9762\u5411 Triton \u7a0b\u5e8f\u7684\u591a\u540e\u7aef\u8c03\u8bd5\u4e0e\u6027\u80fd\u5206\u6790\u5de5\u5177\uff0c\u4e3a NVIDIA GPU \u53ca\u591a\u79cd AI \u52a0\u901f\u8bbe\u5907\u63d0\u4f9b\u4e00\u81f4\u7684\u89c2\u6d4b\u5de5\u4f5c\u6d41\uff1a\u5728\u7f16\u8bd1\u671f\u548c\u8fd0\u884c\u671f\u89c2\u6d4b Triton kernel\uff0c\u5c06\u6e90\u7801\u4e0a\u4e0b\u6587\u3001Triton IR \u64cd\u4f5c\u4e0e\u8bbe\u5907\u4e8b\u4ef6\u5173\u8054\u8d77\u6765\uff0c\u5e76\u628a\u91c7\u96c6\u7684\u6570\u636e\u8f6c\u5316\u4e3a\u62a5\u544a\uff0c\u5e2e\u52a9\u5f00\u53d1\u8005\u5206\u6790\u4e0d\u540c\u52a0\u901f\u5668\u540e\u7aef\u4e0a\u7684\u7a0b\u5e8f\u6b63\u786e\u6027\u3001\u5185\u5b58\u884c\u4e3a\u548c\u6027\u80fd\u8868\u73b0\u3002</p>", "a[href=\"user_guide/debugger.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Debugger<a class=\"headerlink\" href=\"#debugger\" title=\"Link to this heading\">#</a></h1><p>FlagPrism Debugger \u7528\u4e8e\u89c2\u5bdf Triton kernel \u5185\u90e8\u7684\u6570\u503c\u3001\u5185\u5b58\u8bbf\u95ee\u548c operation \u6267\u884c\u72b6\u6001\u3002\u5b83\u5c06\u7f16\u8bd1\u671f\u9759\u6001 metadata \u4e0e device \u8fd0\u884c\u671f\u8bb0\u5f55\u5173\u8054\uff0c\u5bfc\u51fa Triton \u8bed\u53e5\u7ea7\u62a5\u544a\u3001IR op \u7ea7\u62a5\u544a\u548c level-2 NumPy artifact\uff0c\u7528\u4e8e\u5b9a\u4f4d\u6570\u503c\u5f02\u5e38\u3001\u5f02\u5e38\u8bbf\u5b58\u548c kernel \u5185\u90e8\u6570\u636e\u6d41\u95ee\u9898\u3002</p><p>\u52a8\u6001\u91c7\u96c6\u548c hidden-argument launch \u8def\u5f84\u5df2\u5728\u6607\u817e/CANN9\u3001\u5929\u6570/CoreX 4.4\uff08LLVM 22\uff09\u3001MUSA/mthreads 4.3.5 \u4e0e NVIDIA CUDA \u540e\u7aef\u9a8c\u8bc1\u3002</p>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u9879\u76ee\u94fe\u63a5<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
